(function(){const t=240,o=160;let n=0,s=0;return{init:function(t){n=t,s=0},draw:function(h){"ram";h.setColor(3);const a=5+2*n,i=s/45;if(s>0){h.setColor(0);for(let n=30;n<340;n+=55){const i=n+22*Math.sin((s-1)/18+n),c=(s-1)/30+.01*n;for(let n=0;n<a;n++){const s=c+6.283*n/a,r=c+6.283*(n+1)/a;h.drawLine(t+i*Math.cos(s)|0,o+.75*i*Math.sin(s)|0,t+i*Math.cos(r)|0,o+.75*i*Math.sin(r)|0)}}h.setColor(3)}for(let n=30;n<340;n+=55){const c=n+22*Math.sin(s/18+n),r=i+.01*n;for(let n=0;n<a;n++){const s=r+6.283*n/a,i=r+6.283*(n+1)/a;h.drawLine(t+c*Math.cos(s)|0,o+.75*c*Math.sin(s)|0,t+c*Math.cos(i)|0,o+.75*c*Math.sin(i)|0)}}s++}}});